// Compiles the WebAssembly kernels from their text sources (src/engine/*.wat) and writes them,
// base64-encoded, into src/engine/wasm-kernels.js, which the engine imports. Run after editing a
// .wat file:   npm run build:wasm
// (`npm test` fails if the generated file doesn't match the sources.)
import { readFileSync, writeFileSync } from "node:fs";
import wabtInit from "wabt";

export const KERNELS = [
  // name in wasm-kernels.js, source, wabt features
  { name: "STEP_KERNEL_B64", file: "chain-step.wat", features: {}, about: "one pull of a chain (push form), and a dot product" },
  { name: "PULL_KERNEL_B64", file: "chain-pull.wat", features: { threads: true }, about: "one pull over a range of states (pull form, shared memory, for helper threads)" },
  { name: "RENEWAL_KERNEL_B64", file: "renewal-simd.wat", features: { simd: true }, about: "Horner and Parseval loops of the layered method, two frequencies at a time (SIMD)" },
];

const engineDir = new URL("../src/engine/", import.meta.url);

export async function compileKernels() {
  const wabt = await wabtInit();
  return KERNELS.map((k) => {
    const mod = wabt.parseWat(k.file, readFileSync(new URL(k.file, engineDir), "utf8"), k.features);
    mod.validate(k.features);
    const { buffer } = mod.toBinary({});
    mod.destroy();
    return { ...k, b64: Buffer.from(buffer).toString("base64") };
  });
}

export function render(compiled) {
  return [
    "// Generated by scripts/build-wasm.mjs from the .wat files next to this one. Don't edit by hand:",
    "// change the .wat source and run `npm run build:wasm`.",
    ...compiled.flatMap((k) => ["", `// ${k.file}: ${k.about}`, `export const ${k.name} = "${k.b64}";`]),
    "",
  ].join("\n");
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const text = render(await compileKernels());
  writeFileSync(new URL("wasm-kernels.js", engineDir), text);
  console.log(`wrote src/engine/wasm-kernels.js (${KERNELS.length} kernels)`);
}
